<?php require 'includes/auth.php';require_role('buyer');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post('action');$item=(int)post('item_id');$s=$pdo->prepare('SELECT ci.*,p.stock,p.min_quantity FROM cart_items ci JOIN carts c ON c.id=ci.cart_id JOIN products p ON p.id=ci.product_id WHERE ci.id=? AND c.user_id=?');$s->execute([$item,user()['id']]);$ci=$s->fetch();if($ci){if($action==='remove')$pdo->prepare('DELETE FROM cart_items WHERE id=?')->execute([$item]);else{$q=(float)post('quantity');if($q>=$ci['min_quantity']&&$q<=$ci['stock'])$pdo->prepare('UPDATE cart_items SET quantity=? WHERE id=?')->execute([$q,$item]);else flash('error','Quantity is outside the available stock range.');}}redirect('cart.php');}
$s=$pdo->prepare('SELECT ci.id item_id,ci.quantity,p.*,sp.shop_name FROM cart_items ci JOIN carts c ON c.id=ci.cart_id JOIN products p ON p.id=ci.product_id JOIN seller_profiles sp ON sp.id=p.seller_id WHERE c.user_id=? ORDER BY sp.shop_name');$s->execute([user()['id']]);$items=$s->fetchAll();$total=array_sum(array_map(fn($i)=>$i['quantity']*$i['price'],$items));$pageTitle='Your cart';require 'includes/header.php';?><div class="page-title"><p class="eyebrow">YOUR SELECTION</p><h1>Your cart</h1></div><?php if($items):?><div class="cart-layout"><section class="cart-items"><?php foreach($items as $i):?><article class="cart-item"><div class="thumb"><?php if($i['image_path']):?><img src="<?=url($i['image_path'])?>" alt=""><?php else:?>🐟<?php endif;?></div><div><h3><?=e($i['name'])?></h3><p>From <?=e($i['shop_name'])?> · ₹<?=number_format($i['price'],2)?>/kg</p></div><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="item_id" value="<?=$i['item_id']?>"><input type="hidden" name="action" value="update"><input class="quantity" name="quantity" type="number" step="0.5" min="<?=$i['min_quantity']?>" max="<?=$i['stock']?>" value="<?=$i['quantity']?>"><button class="text-button">Update</button></form><strong>₹<?=number_format($i['quantity']*$i['price'],2)?></strong><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="item_id" value="<?=$i['item_id']?>"><input type="hidden" name="action" value="remove"><button class="icon-button" data-confirm="Remove this item?">×</button></form></article><?php endforeach;?></section><aside class="summary"><h2>Order summary</h2><p><span>Items subtotal</span><strong>₹<?=number_format($total,2)?></strong></p><p><span>Delivery</span><strong>Calculated at checkout</strong></p><hr><p class="total"><span>Total</span><strong>₹<?=number_format($total,2)?></strong></p><a class="button block" href="checkout.php">Proceed to checkout</a></aside></div><?php else:?><div class="empty">🛒<h2>Your cart is waiting for a catch.</h2><a class="button" href="products.php">Browse fish</a></div><?php endif;require 'includes/footer.php'; ?>
